const getStore = () => { try { return JSON.parse(localStorage.getItem('iqra-profile') || '{}'); } catch { return {}; } };
let state = { page: 'home', lang: 'en', goal: 10, ...getStore(), recording: false, stream: null, recorder: null, chunks: [], draftUrl: null, timer: null, elapsed: 0, audioSaved: false };
const $ = selector => document.querySelector(selector);
const t = key => (COPY[state.lang] || COPY.en)[key] || COPY.en[key] || key;
function persist() { const { page, recording, stream, recorder, chunks, draftUrl, timer, elapsed, ...saved } = state; localStorage.setItem('iqra-profile', JSON.stringify(saved)); }
function toast(message) { const node = $('#toast'); node.textContent = message; node.classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => node.classList.remove('show'), 2300); }
function esc(value) { return String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function currentDate() { return new Date().toISOString().slice(0,10); }
function secondsOn(date) { return (state.sessions||[]).filter(s=>s.date===date).reduce((sum,s)=>sum+(s.seconds||0),0); }
function setPage(page) { if (state.recording) stopRecording(); $('#modalRoot').innerHTML=''; state.page = page; render(); window.scrollTo({top:0,behavior:'smooth'}); if(page==='practice'&&state.audioSaved&&!state.draftUrl)restoreBlob(); }
function navMarkup() { return `<div class="top-actions"><button class="icon-button" id="soundToggle" aria-label="${t('listen')}">♪</button><button class="avatar" id="profileButton" aria-label="${t('settings')}">Z</button></div>`; }
function homePage() {
  const minutes = Math.floor(secondsOn(currentDate())/60), done = Math.min(100, Math.round(minutes / state.goal * 100));
  return `<div class="eyebrow">${t('hello')}</div><h1 class="greeting">${t('homeTitle')}</h1><p class="subtle">${t('welcome')}</p>
    <section class="hero-card"><div class="eyebrow">${t('todaysFocus')}</div><div class="hero-title" lang="ar" dir="rtl">${VERSE.text}</div><div class="hero-meta">${VERSE.surah} · ${VERSE.key} &nbsp;·&nbsp; ${t('reciter')}</div><div class="hero-actions"><button class="button button-primary" data-goto="practice">▷ &nbsp;${t('start')}</button><button class="button button-glass" data-goto="read">${t('read')}</button></div></section>
    <div class="section-head"><h2>${t('goal')}</h2><button class="text-action" data-settings>${state.goal} ${t('minutes')}</button></div>
    <div class="daily-card"><div class="ring"><strong>${done}%</strong></div><div class="daily-copy"><strong>${minutes} / ${state.goal} ${t('minutes')}</strong><span>${t('keepGoing')}</span></div><div class="streak">✦ ${state.streak || 0} ${t('streak')}</div></div>
    <div class="section-head"><h2>${t('continue')}</h2><button class="text-action" data-goto="progress">${t('progress')} →</button></div>
    <div class="quick-grid"><button class="quick-card" data-goto="read"><span class="quick-icon">▤</span><strong>${t('read')}</strong><span>${VERSE.surah} · ${VERSE.key}</span></button><button class="quick-card" data-goto="learn"><span class="quick-icon">✦</span><strong>${t('review')}</strong><span>${t('reviewStatus')}</span></button></div><div class="connection" id="connection">${navigator.onLine ? t('online') : t('offline')}</div>`;
}
function readerPage() { return `<div class="page-heading"><div class="eyebrow">${t('reciter')}</div><h1>${t('readTitle')}</h1><p class="subtle">${t('begin')}</p></div>
    <div class="reader-top"><div class="select-wrap"><select aria-label="Surah"><option>1 · Al-Fātiḥah</option></select></div><button class="button button-light" data-goto="practice">◉ &nbsp;${t('practise')}</button></div>
    <div class="reader-surah"><div class="surah-arabic" lang="ar" dir="rtl">${VERSE.surahArabic}</div><p>Al-Fātiḥah · The Opening</p></div>
    <article class="verse-row"><span class="verse-number">١</span><div style="flex:1"><div class="verse-text" lang="ar" dir="rtl">${VERSE.text}</div><div class="verse-tools"><button class="mini-icon" data-bookmark aria-label="Bookmark">${state.bookmarks?.includes(VERSE.key) ? '♥':'♡'}</button><button class="mini-icon" data-reference aria-label="${t('listen')}">▷</button><button class="mini-icon" data-goto="practice" aria-label="${t('practise')}">◉</button></div></div></article>
    <div class="recitation-player"><div><strong>${t('reference')}</strong><span>Mishary Rashid Alafasy · Alafasy (Murattal)</span></div><audio id="quranAudio" controls preload="none" src="assets/audio/alafasy-001001.mp3" aria-label="Al-Fatiha verse 1 recitation by Mishary Rashid Alafasy"></audio><small>Bundled for offline use · recording copyright remains with the reciter. <a href="https://alquran.cloud/terms-and-conditions" target="_blank" rel="noreferrer">Audio terms</a></small></div><div class="source-note">${esc(VERSE.source)} <a href="https://tanzil.net" target="_blank" rel="noreferrer">tanzil.net</a>.</div>`; }
function practicePage() {
  const hasDraft = Boolean(state.draftUrl), isRec = state.recording;
  return `<div class="page-heading"><div class="eyebrow">${t('reciter')}</div><h1>${t('practiceTitle')}</h1><p class="subtle">${t('begin')}</p></div>
    <section class="practice-verse"><div class="verse-number">١</div><div class="verse-text" lang="ar" dir="rtl">${VERSE.text}</div><div class="verse-tools"><button class="mini-icon" data-reference aria-label="${t('listen')}">▷</button><span class="subtle" style="align-self:center">${VERSE.surah} · ${VERSE.key}</span></div><audio id="quranAudio" controls preload="none" style="width:100%;height:36px;margin-top:12px" src="assets/audio/alafasy-001001.mp3" aria-label="Al-Fatiha verse 1 recitation by Mishary Rashid Alafasy"></audio><small style="display:block;margin-top:7px;color:#7d8780">Mishary Rashid Alafasy · included in app</small></section>
    <section class="record-panel"><div class="record-status" id="recordStatus">${isRec ? `${t('stop')} · ${formatTime(state.elapsed)}` : t('record')}</div><div class="waveform ${isRec?'live':''}" aria-hidden="true">${Array.from({length:25},()=>'<i></i>').join('')}</div><button class="record-button ${isRec?'recording':''}" id="recordButton" aria-label="${isRec?t('stop'):t('record')}">${isRec?'■':'●'}</button><p class="record-caption">${isRec ? `${formatTime(state.elapsed)} · ${t('stop')}` : t('notAnalyzed')}</p>
      ${hasDraft ? `<div class="saved-audio"><audio id="draftAudio" controls src="${state.draftUrl}"></audio><div class="save-row"><label><input type="checkbox" id="saveAudioCheck" ${state.audioSaved?'checked':''}/> ${t('saveAudio')}</label>${state.audioSaved?`<button id="deleteSaved">${t('delete')}</button>`:''}</div><div class="record-caption">${state.audioSaved?t('saved'):t('unsaved')}</div></div>`:''}</section>
    <div class="notice"><span>ⓘ</span><div><b>${t('notAnalyzed')}</b><p>${t('notAnalyzedCopy')}</p></div></div>
    <button class="button button-outline" style="width:100%;margin-top:14px" data-analysis>${t('inconclusive')}</button>`;
}
const lessons = [
  {id:'makharij',icon:'م',title:'Makharij al-ḥurūf',sub:'Where Arabic letters are articulated',ar:'مَخَارِجُ الْحُرُوفِ'},
  {id:'ghunnah',icon:'ن',title:'Ghunnah',sub:'Nasal resonance · draft learning note',ar:'غُنَّة'},
  {id:'madd',icon:'ٓ',title:'Madd',sub:'The lengthening of a vowel · draft note',ar:'مَدّ'},
  {id:'qalqalah',icon:'ق',title:'Qalqalah',sub:'An echoing quality on selected letters',ar:'قَلْقَلَة'}
];
function learnPage() { return `<div class="page-heading"><div class="eyebrow">${t('reviewStatus')}</div><h1>${t('learnTitle')}</h1><p class="subtle">${t('lessonSource')}</p></div><div class="lesson-list">${lessons.map(item=>`<button class="lesson-card" data-lesson="${item.id}"><span class="lesson-badge" lang="ar">${item.icon}</span><span><strong>${item.title}</strong><small>${item.sub}</small></span><span class="lesson-arrow">›</span></button>`).join('')}</div><div class="source-note">${t('lessonSource')} <br/>No Tajweed assessment is made in this prototype.</div>`; }
function progressPage() { const sessions=state.sessions||[], mins=state.minutes||0;return `<div class="page-heading"><div class="eyebrow">${t('progressDesc')}</div><h1>${t('progressTitle')}</h1></div><div class="progress-hero"><div class="ring"><strong>✦</strong></div><div><strong>${mins} ${t('minutes')}</strong><span>${t('minutesPractised')}</span></div></div><div class="stats-grid"><div class="stat"><strong>${sessions.length}</strong><span>${t('attempts')}</span></div><div class="stat"><strong>${state.streak||0}</strong><span>${t('streak')}</span></div></div><div class="section-head"><h2>${t('continue')}</h2></div>${sessions.length?sessions.slice().reverse().slice(0,8).map(s=>`<div class="history-item"><span>${VERSE.surah} · ${VERSE.key}<small>${esc(s.date)} · ${formatTime(s.seconds||0)}</small></span><span class="count">${t('inconclusive')}</span></div>`).join(''):`<div class="empty-state"><strong>${t('noHistory')}</strong>${t('progressDesc')}</div>`}<div class="source-note">${t('onDevice')} ${t('inconclusiveCopy')}</div>`; }
function formatTime(seconds) { const m=Math.floor(seconds/60),s=seconds%60;return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`; }
function render() {
  const page = ({home:homePage,read:readerPage,practice:practicePage,learn:learnPage,progress:progressPage})[state.page] || homePage;
  document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';
  document.querySelector('.brand').setAttribute('aria-label',t('navHome'));document.querySelector('.top-actions').outerHTML=navMarkup();
  $('#main').innerHTML=page();
  document.querySelectorAll('.nav-item').forEach(btn=>{const p=btn.dataset.page;btn.classList.toggle('active',state.page===p);btn.querySelector('small').textContent=t(({home:'navHome',read:'navRead',practice:'navPractice',learn:'navLearn',progress:'navProgress'})[p]);});
  if(state.recording) tickLabel();
}
function showModal(title, content) { $('#modalRoot').innerHTML=`<div class="modal-backdrop" data-backdrop><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="eyebrow">Iqra</div><h2 id="modalTitle">${title}</h2>${content}<div class="modal-actions"><button class="button button-green" data-close>${t('close')}</button></div></section></div>`;$('#modalRoot').querySelector('[data-close]').focus(); }
function settingsModal() { showModal(t('settings'),`<div class="toggle-row"><span>${t('language')}</span><select id="languageSelect" aria-label="${t('language')}"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="fr" ${state.lang==='fr'?'selected':''}>Français</option><option value="ar" ${state.lang==='ar'?'selected':''}>العربية</option></select></div><div class="toggle-row"><span>${t('goal')}</span><select id="goalSelect"><option value="5">5 ${t('minutes')}</option><option value="10">10 ${t('minutes')}</option><option value="15">15 ${t('minutes')}</option><option value="20">20 ${t('minutes')}</option></select></div><div class="toggle-row"><span>${t('privacy')}</span><span>◉ ${t('onDevice')}</span></div><div class="source-note">${t('saveAudioSetting')}<br/>Recordings are never uploaded by this prototype.</div>`);
  $('#languageSelect').value=state.lang;$('#goalSelect').value=state.goal;
}
function lessonModal(id) { const item=lessons.find(x=>x.id===id); if(!item)return; const text=id==='makharij'?'Makharij describes the places from which Arabic letters are articulated. Listen to a qualified teacher and practise gently; a written note cannot replace guided listening.':id==='ghunnah'?'Ghunnah is a nasal resonance associated with specific letters and rules. Its duration and application depend on the recitation context. This note needs qualified review.':id==='madd'?'Madd refers to lengthening a vowel sound. The type and duration depend on the letters and recitation context. This note needs qualified review.':'Qalqalah describes a quality of sound on ق ط ب ج د under specific conditions. Learn it with verified examples and teacher guidance.'; showModal(`${t('lesson')}: ${item.title}`,`<div class="arabic-example" lang="ar">${item.ar}</div><p>${text}</p><p><b>${t('reviewStatus')}</b></p><p>${t('lessonSource')}</p><button class="button button-light" data-goto="practice">${t('practise')}</button>`); }
function microphoneError(error) {
  if (!window.isSecureContext || !navigator.mediaDevices?.getUserMedia) return 'Microphone needs a secure page. On this computer open http://localhost:4173. A phone needs HTTPS or an installed app.';
  if (!window.MediaRecorder) return 'This browser cannot record audio. Try an up-to-date version of Chrome, Edge, or Safari.';
  if (error?.name === 'NotAllowedError' || error?.name === 'PermissionDeniedError') return 'Microphone permission is blocked. Allow it in the browser site settings, then reload this page.';
  if (error?.name === 'NotFoundError' || error?.name === 'DevicesNotFoundError') return 'No microphone was found. Connect or enable a microphone and try again.';
  if (error?.name === 'NotReadableError' || error?.name === 'TrackStartError') return 'The microphone is busy or blocked by your device. Close other apps using it and try again.';
  if (error?.name === 'NotSupportedError') return 'This browser cannot record audio. Try an up-to-date version of Chrome, Edge, or Safari.';
  return `Could not start the microphone${error?.name ? ` (${error.name})` : ''}. Check browser permission and device settings, then try again.`;
}
async function startRecording() { if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){const message=microphoneError();const caption=document.querySelector('.record-caption');if(caption)caption.textContent=message;toast(message);return;}try{state.stream=await navigator.mediaDevices.getUserMedia({audio:true});state.chunks=[];const options=MediaRecorder.isTypeSupported('audio/webm;codecs=opus')?{mimeType:'audio/webm;codecs=opus'}:{};state.recorder=new MediaRecorder(state.stream,options);state.recorder.ondataavailable=e=>{if(e.data.size)state.chunks.push(e.data)};state.recorder.onstop=()=>{state.stream?.getTracks().forEach(track=>track.stop());state.stream=null;if(state.draftUrl)URL.revokeObjectURL(state.draftUrl);const blob=new Blob(state.chunks,{type:state.recorder.mimeType||'audio/webm'});state.draftUrl=URL.createObjectURL(blob);state.elapsed=Math.min(state.elapsed,3599);state.audioSaved=false;const sessions=state.sessions||[];sessions.push({date:currentDate(),seconds:state.elapsed});state.sessions=sessions;state.minutes=Math.floor(sessions.reduce((sum,s)=>sum+(s.seconds||0),0)/60);state.streak=calcStreak(sessions);persist();state.recording=false;render();};state.elapsed=0;state.recording=true;state.recorder.start();state.timer=setInterval(()=>{state.elapsed++;tickLabel();},1000);render();}catch(error){state.recording=false;state.stream?.getTracks().forEach(track=>track.stop());state.stream=null;const message=microphoneError(error);const caption=document.querySelector('.record-caption');if(caption)caption.textContent=message;toast(message);}}
function calcStreak(sessions){const dates=new Set(sessions.map(x=>x.date));let d=new Date();if(!dates.has(d.toISOString().slice(0,10)))d.setDate(d.getDate()-1);let n=0;while(dates.has(d.toISOString().slice(0,10))){n++;d.setDate(d.getDate()-1);}return n;}
function stopRecording(){if(!state.recording)return;clearInterval(state.timer);state.timer=null;state.recording=false;state.recorder?.stop();}
function tickLabel(){const s=$('#recordStatus');if(s)s.textContent=`${t('stop')} · ${formatTime(state.elapsed)}`;const caption=document.querySelector('.record-caption');if(caption&&state.recording)caption.textContent=`${formatTime(state.elapsed)} · ${t('stop')}`;}
function saveBlob(blob){return new Promise((resolve,reject)=>{const req=indexedDB.open('iqra-private',1);req.onupgradeneeded=()=>req.result.createObjectStore('recordings');req.onerror=()=>reject(req.error);req.onsuccess=()=>{const db=req.result,tx=db.transaction('recordings','readwrite');tx.objectStore('recordings').put(blob,'latest');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);};});}
function restoreBlob(){if(!('indexedDB' in window))return;const req=indexedDB.open('iqra-private',1);req.onsuccess=()=>{const get=req.result.transaction('recordings').objectStore('recordings').get('latest');get.onsuccess=()=>{if(get.result&&state.page==='practice'){state.draftUrl=URL.createObjectURL(get.result);render();}};};}
function deleteBlob(){return new Promise((resolve,reject)=>{const req=indexedDB.open('iqra-private',1);req.onsuccess=()=>{const tx=req.result.transaction('recordings','readwrite');tx.objectStore('recordings').delete('latest');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);};req.onerror=()=>reject(req.error);});}
document.addEventListener('click', async event=>{
  const nav=event.target.closest('.nav-item');if(nav){setPage(nav.dataset.page);return;}
  const goto=event.target.closest('[data-goto]');if(goto){setPage(goto.dataset.goto);return;}
  if(event.target.closest('[data-settings],#profileButton')){settingsModal();return;}
  if(event.target.closest('[data-close]')||event.target.matches('[data-backdrop]')){$('#modalRoot').innerHTML='';return;}
  if(event.target.closest('[data-reference],#soundToggle')){let audio=$('#quranAudio');if(!audio){setPage('read');setTimeout(()=>$('#quranAudio')?.play().catch(()=>toast(t('audioNotReady'))),180);}else audio.play().catch(()=>toast(t('audioNotReady')));return;}
  if(event.target.closest('[data-bookmark]')){state.bookmarks=state.bookmarks||[];const at=state.bookmarks.indexOf(VERSE.key);if(at<0){state.bookmarks.push(VERSE.key);toast(t('bookmarked'));}else{state.bookmarks.splice(at,1);toast(t('removed'));}persist();render();return;}
  if(event.target.closest('[data-lesson]')){lessonModal(event.target.closest('[data-lesson]').dataset.lesson);return;}
  if(event.target.closest('#recordButton')){state.recording?stopRecording():startRecording();return;}
  if(event.target.closest('[data-analysis]')){showModal(t('inconclusive'),`<p>${t('inconclusiveCopy')}</p><p>${t('notAnalyzedCopy')}</p>`);return;}
  if(event.target.closest('#deleteSaved')){await deleteBlob().catch(()=>{});state.audioSaved=false;persist();render();toast(t('delete'));return;}
});
document.addEventListener('change',async event=>{
  if(event.target.id==='languageSelect'){state.lang=event.target.value;persist();$('#modalRoot').innerHTML='';render();}
  if(event.target.id==='goalSelect'){state.goal=Number(event.target.value);persist();$('#modalRoot').innerHTML='';render();}
  if(event.target.id==='saveAudioCheck'){if(event.target.checked&&state.chunks.length){try{await saveBlob(new Blob(state.chunks,{type:state.recorder?.mimeType||'audio/webm'}));state.audioSaved=true;persist();render();toast(t('saved'));}catch{event.target.checked=false;toast('Could not save recording on this device.');}}else if(!event.target.checked){await deleteBlob().catch(()=>{});state.audioSaved=false;persist();render();}}
});
window.addEventListener('online',()=>{const c=$('#connection');if(c){c.textContent=t('online');c.classList.remove('offline');}});window.addEventListener('offline',()=>{const c=$('#connection');if(c){c.textContent=t('offline');c.classList.add('offline');}});
window.addEventListener('beforeunload',()=>{if(state.stream)state.stream.getTracks().forEach(track=>track.stop());if(state.draftUrl)URL.revokeObjectURL(state.draftUrl);});
if('serviceWorker' in navigator && location.protocol.startsWith('http')) navigator.serviceWorker.register('./sw.js').catch(()=>{});
render();if(state.page==='practice'&&state.audioSaved)restoreBlob();
